from math import comb

def binom(k, n, p):
    return comb(n, k) * p ** k * (1 - p) ** (n - k)
probs = [binom(k, 5, 0.7) for k in range(6)]
print([round(v, 3) for v in probs])   # [0.002, 0.028, 0.132, 0.309, 0.36, 0.168]
print(round(sum(probs), 2))           # 1.0

